package com.adria.transaction.mcp;import com.adria.transaction.domain.BankTransaction;import com.adria.transaction.service.TransactionService;import org.springframework.stereotype.Component;import org.springframework.ai.mcp.server.annotation.McpTool;import org.springframework.ai.mcp.server.annotation.McpToolParam;import java.util.*;import java.math.*;@Component public class TransactionMcpTools{private final TransactionService service;public TransactionMcpTools(TransactionService s){service=s;}@McpTool(description="Lister les transactions bancaires")public List<BankTransaction> getTransactions(){return service.all();}@McpTool(description="Créer une transaction bancaire après validation métier")public BankTransaction createTransaction(@McpToolParam(description="UUID du compte")String accountId,@McpToolParam(description="Montant positif")String amount,@McpToolParam(description="Devise ISO")String currency){return service.create(UUID.fromString(accountId),new BigDecimal(amount),currency,"OTHER","UNKNOWN");}}